    /* Test the specific case that might crash */
    printf("Testing LZ4_decompress_safe_partial_usingDict with small external dict...\n");
    result = LZ4_decompress_safe_partial_usingDict((char const*)data, dst, size,
                                  dstCapacity, dstCapacity, smallDict, smallDictSize);
    printf("Result: %d\n", result);

    printf("Testing LZ4_decompress_safe_partial_usingDict with large external dict...\n");
